         {
             uid: '0xe160ac1bd3606a287b4d53d5d1d6da5895f65b4b4bab6d93aaf5046e48167ade',
             value: 0
         }],
         signatures: [{
             v: 28,
             r: '0x148c...b25b',
             s: '0x5a72...be22'
         },
         {
             v: 28,
             r: '0x487s...67bb',
             s: '0x12ad...2366'
         }],
         revoker: '0x244934dd3e31bE2c81f84ECf0b3E6329F5381992',
